    /* ===== compact the LIVE crosspoints into one list =====
     * The fold above left the accumulate path reading coefficients
     * only, but it still WALKED all 25 crosspoints every sample to
     * find the two or three that are live. That walk is control
     * state too -- which crosspoints are on is a control-rate fact --
     * so it resolves here, into a dense list of
     * (source address, bus accumulator, coefficient) triples and a
     * count. The audio path then iterates over live crosspoints
     * only, with no test of any kind in it.
     *
     * Cost is one 25-entry walk per BLOCK against 25 walked per
     * SAMPLE; a channel assigned to main only goes from 25
     * iterations per sample to 2. */
#if DSP4_BLOCK_KERNELS
    r12 = BLK_CHAIN_A;                /* post-fader mono block */
#else
    r12 = _buf_C1_FDR_24;              /* post-fader mono word  */
#endif
    l0 = 0;
    l3 = 0;
    l4 = 0;
    l5 = 0;
    i0 = _rtg_list_C1_RTG_24;
    r10 = 0;                          /* live count */

    r1 = dm(_rtg_mlq_C1_RTG_24);
    r1 = pass r1;
    if eq jump (pc, .lb_noml_C1_RTG_24);
    dm(i0, 1) = r12;
    r2 = _bus_acc_main_l;
    dm(i0, 1) = r2;
    dm(i0, 1) = r1;
    r10 = r10 + 1;
.lb_noml_C1_RTG_24:
    r1 = dm(_rtg_mrq_C1_RTG_24);
    r1 = pass r1;
    if eq jump (pc, .lb_nomr_C1_RTG_24);
    dm(i0, 1) = r12;
    r2 = _bus_acc_main_r;
    dm(i0, 1) = r2;
    dm(i0, 1) = r1;
    r10 = r10 + 1;
.lb_nomr_C1_RTG_24:
    r1 = dm(_rtg_subq_C1_RTG_24);
    r1 = pass r1;
    if eq jump (pc, .lb_nosub_C1_RTG_24);
    dm(i0, 1) = r12;
    r2 = _bus_acc_sub;
    dm(i0, 1) = r2;
    dm(i0, 1) = r1;
    r10 = r10 + 1;
.lb_nosub_C1_RTG_24:

    i4 = _rtg_grpq_C1_RTG_24;
    i3 = _bus_acc_grp_ptrs;
    lcntr = 4, do .lb_grp_C1_RTG_24 until lce;
        r1 = dm(i4, 1);
        r3 = dm(i3, 1);
        r1 = pass r1;
        if eq jump (pc, .lb_gskip_C1_RTG_24);
        dm(i0, 1) = r12;
        dm(i0, 1) = r3;
        dm(i0, 1) = r1;
        r10 = r10 + 1;
    .lb_gskip_C1_RTG_24:
        nop;
    .lb_grp_C1_RTG_24:
        nop;

    i4 = _rtg_aux_sq_C1_RTG_24;
    i5 = _rtg_aux_src_C1_RTG_24;
    i3 = _bus_acc_aux_ptrs;
    lcntr = 12, do .lb_aux_C1_RTG_24 until lce;
        r1 = dm(i4, 1);
        r3 = dm(i3, 1);
        r2 = dm(i5, 1);
        r1 = pass r1;
        if eq jump (pc, .lb_askip_C1_RTG_24);
        dm(i0, 1) = r2;
        dm(i0, 1) = r3;
        dm(i0, 1) = r1;
        r10 = r10 + 1;
    .lb_askip_C1_RTG_24:
        nop;
    .lb_aux_C1_RTG_24:
        nop;

    i4 = _rtg_fx_sq_C1_RTG_24;
    i5 = _rtg_fx_src_C1_RTG_24;
    i3 = _bus_acc_fx_ptrs;
    lcntr = 6, do .lb_fx_C1_RTG_24 until lce;
        r1 = dm(i4, 1);
        r3 = dm(i3, 1);
        r2 = dm(i5, 1);
        r1 = pass r1;
        if eq jump (pc, .lb_fskip_C1_RTG_24);
        dm(i0, 1) = r2;
        dm(i0, 1) = r3;
        dm(i0, 1) = r1;
        r10 = r10 + 1;
    .lb_fskip_C1_RTG_24:
        nop;
    .lb_fx_C1_RTG_24:
        nop;

    dm(_rtg_n_C1_RTG_24) = r10;

#if DSP4_BLOCK_KERNELS && !DSP4_CTL_ALWAYS
    /* Ramps are not SPI writes, so the epoch never sees them: while
     * any send ramp still has frames its coefficient changes every
     * block, and the prep has to keep running. r11 was accumulated
     * inside the two send-ramp loops above, where the frame count
     * was already in a register -- one instruction each, against the
     * ten a separate 18-word scan cost, in a PM section with about a
     * thousand words left in the paired build. It survives the
     * pickoff-resolution and list-build loops between them; neither
     * of those touches r11. */
    dm(_rtg_busy + 23) = r11;
#endif

.rtg_acc_C1_RTG_24:
    /* ===== crosspoint accumulate =====
     * Nothing here reads control state and nothing here branches on
     * it. Every iteration is a live crosspoint: fetch its source,
     * its bus and its coefficient, and MAC. */
    r5 = dm(_rtg_n_C1_RTG_24);
    r5 = pass r5;
    if eq jump (pc, .rtg_tail_C1_RTG_24);
    l1 = 0;
    l2 = 0;
    l6 = 0;
    i6 = _rtg_list_C1_RTG_24;
    lcntr = r5, do .rtg_xp_C1_RTG_24 until lce;
        r6 = dm(i6, 1);               /* source            */
        r3 = dm(i6, 1);               /* bus accumulator   */
        r1 = dm(i6, 1);               /* coefficient       */
#if DSP4_BLOCK_KERNELS
        i0 = r6;
        i2 = r3;
        call _acc64_mac_blk;
#else
        i1 = r6;
        r0 = dm(i1, 0);
        i2 = r3;
        call _acc64_mac;
#endif
    .rtg_xp_C1_RTG_24:
        nop;
.rtg_tail_C1_RTG_24:

    r0 = dm(_tap_post_fader_C1_FDR_24);
    dm(_buf_C1_RTG_24) = r0;
    rts;
_C1_RTG_24_process.end:
